# Run from the tree root: Rscript meta-regression/tests/review-p08/reference-metafor.R
# This fixture is generated by real R, never by the JavaScript under test.
suppressPackageStartupMessages(library(metafor))

# Only serialize the finite numbers, strings and lists used by this fixture.
# Keep 17 significant digits so JSON round-trips R doubles without rounding.
# No optional JSON package is needed on the reference runner.
json <- function(value) {
  if (is.list(value)) {
    items <- vapply(value, json, character(1))
    if (!is.null(names(value))) {
      items <- paste0(vapply(names(value), json, character(1)), ":", items)
      return(paste0("{", paste(items, collapse = ","), "}"))
    }
    return(paste0("[", paste(items, collapse = ","), "]"))
  }
  if (length(value) != 1L) return(json(as.list(value)))
  if (is.character(value)) return(encodeString(value, quote = '"'))
  if (is.numeric(value) && is.finite(value)) return(sprintf("%.17g", value))
  stop("Unsupported or non-finite reference value")
}

reference <- function(id, yi, vi, x) {
  control <- list(tol = 1e-12, tau2.max = 100 * max(var(yi), vi))
  model <- rma(yi = yi, vi = vi, mods = ~ x, method = "PM", test = "adhoc", control = control)
  null <- rma(yi = yi, vi = vi, method = "PM", test = "adhoc", control = control)
  prediction <- predict(model, newmods = mean(x))
  list(id = id, yi = yi, vi = vi, x = x, control = control,
       expected = list(intercept = unname(model$b[1]), slope = unname(model$b[2]),
         intercept_se = model$se[1], slope_se = model$se[2],
         intercept_ci_lb = model$ci.lb[1], intercept_ci_ub = model$ci.ub[1],
         slope_ci_lb = model$ci.lb[2], slope_ci_ub = model$ci.ub[2],
         tau2_pm = model$tau2, tau2_null = null$tau2, R2_tau2 = model$R2 / 100,
         QE = model$QE, QE_p = model$QEp, QE_df = model$k - model$p,
         pred = prediction$pred, pred_se = prediction$se,
         pi_lo = prediction$pi.lb, pi_hi = prediction$pi.ub))
}

x <- c(-1.5, -0.5, 0.5, 1.5)
yi <- c(-3, -1, 3, 9)
cases <- list(reference("ordinary", yi, rep(1, 4), x),
              reference("scaled", yi * 1e6, rep(1e12, 4), x),
              reference("unequal-variances", c(.1, .3, .5, .2, .9, .4, 1.1, .05),
                        c(.2, .25, .18, .3, .22, .28, .35, .15)^2, 1:8))
# Read the numeric inputs from the existing exported R scripts, which mirror
# configs.json. Evaluate only yi/se/x assignments, not their model or print code.
# No existing paper fixture or reference is changed.
scripts <- c("app-example" = "app_example.R",
             "dat.bcg/e1/ablat" = "dat_bcg_e1_ablat.R",
             "dat.bcg/e1/year" = "dat_bcg_e1_year.R",
             "dat.aloe2013/e1/n" = "dat_aloe2013_e1_n.R",
             "dat.hart1999/e1/year" = "dat_hart1999_e1_year.R",
             "dat.bangertdrowns2004/e1/minutes" = "dat_bangertdrowns2004_e1_minutes.R")
input_dir <- "hub/shared/tests/fixtures/features/meta-regression/rscript"
for (id in names(scripts)) {
  inputs <- new.env(parent = baseenv())
  for (expr in parse(file.path(input_dir, scripts[[id]]))) {
    if (is.call(expr) && identical(expr[[1]], as.name("<-")) &&
        is.symbol(expr[[2]]) && as.character(expr[[2]]) %in% c("yi", "se", "x")) {
      eval(expr, inputs)
    }
  }
  stopifnot(all(c("yi", "se", "x") %in% ls(inputs)))
  cases[[length(cases) + 1]] <- reference(id, inputs$yi, inputs$se^2, inputs$x)
}
out <- list(R = R.version.string, packages = list(metafor = as.character(packageVersion("metafor")),
            stats = as.character(packageVersion("stats")), utils = as.character(packageVersion("utils"))),
            serializer = "base R, 17 significant digits", method = "PM", test = "adhoc", cases = cases)
output_path <- "meta-regression/tests/review-p08/reference-metafor.json"
if (file.exists(output_path)) stop("Reference already exists; refusing to re-baseline it")
writeLines(json(out), output_path, useBytes = TRUE)
cat("Generated", length(cases), "reference cases with", R.version.string,
    "; metafor", as.character(packageVersion("metafor")), "\n")
cat(json(cases[[2]]$expected), "\n")
